/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}
/**
 * One audit row per domain event; day grouping.
 *
 * Owner C implements `@/server/services/activity-service`, which subscribes to
 * the event bus at module init.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/server/repositories/activity-repository", async (importOriginal) => {
  const actual =
    await importOriginal<typeof import("@/server/repositories/activity-repository")>();
  return { ...actual, insertActivity: vi.fn(actual.insertActivity) };
});

import { emit, subscribe, subscriberCount } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import {
  exportActivity,
  groupByDay,
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ActivityEvent } from "@/types/activity";
import type { CommentId, IssueId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("activity", "growth");
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  vi.mocked(activityRepo.insertActivity).mockClear();
});

describe("services/activity-service", () => {
  // subscribe() is registered for each ActivityAction-shaped event type.
  it("subscribes to every event that maps to an ActivityAction", () => {
    const before = subscriberCount("project.created");
    const off = registerActivityListeners();

    // registerActivityListeners() is idempotent per call — each call attaches
    // its own listener set, so calling it a second time adds one more.
    expect(subscriberCount("project.created")).toBe(before + 1);
    expect(subscriberCount("issue.created")).toBeGreaterThanOrEqual(1);
    expect(subscriberCount("member.role_changed")).toBeGreaterThanOrEqual(1);
    expect(subscriberCount("billing.plan_changed")).toBeGreaterThanOrEqual(1);

    off();
    expect(subscriberCount("project.created")).toBe(before);
  });

  // One emit produces exactly one activity row, with the actor and subject.
  it("records one audit row per emitted event", async () => {
    await emit("project.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: tenant.org.createdAt,
      projectId: tenant.project.id,
      name: "Audited project",
      slug: "audited-project",
    });

    const page = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["project.created"],
      limit: 25,
      cursor: null,
    });

    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      orgId: tenant.org.id,
      action: "project.created",
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
    });
  });

  // A second identical emit produces a second row — the log is append-only.
  it("appends rather than de-duplicates repeated events", async () => {
    const payload = {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: tenant.org.createdAt,
      projectId: tenant.project.id,
      name: "Repeat project",
      slug: "repeat-project",
    } as const;

    const before = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["project.created"],
      limit: 100,
      cursor: null,
    });

    await emit("project.created", payload);
    await emit("project.created", payload);

    const after = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["project.created"],
      limit: 100,
      cursor: null,
    });

    expect(after.total).toBe(before.total + 2);
  });

  // A throwing repository must not fail the emit for sibling subscribers.
  it("isolates a write failure from the emitting service", async () => {
    vi.mocked(activityRepo.insertActivity).mockRejectedValueOnce(
      new Error("activity store unavailable"),
    );

    const sibling = vi.fn();
    const offSibling = subscribe("comment.created", sibling);

    await expect(
      emit("comment.created", {
        orgId: tenant.org.id,
        actorId: tenant.userIds.member,
        occurredAt: tenant.org.createdAt,
        commentId: "cmt-isolation" as CommentId,
        issueId: "issue-isolation" as IssueId,
        mentionedUserIds: [],
      }),
    ).resolves.toBeUndefined();

    expect(sibling).toHaveBeenCalledTimes(1);
    offSibling();
  });

  // groupByDay buckets rows into ActivityGroup entries keyed by calendar day.
  it("groups the feed into calendar days", () => {
    const orgId = tenant.org.id;
    const build = (id: string, day: string): ActivityEvent => ({
      id: id as ActivityEvent["id"],
      orgId,
      action: "issue.created",
      actorId: null,
      subjectKind: "issue",
      subjectId: "s1",
      projectId: null,
      summary: "Created issue",
      metadata: {},
      occurredAt: `${day}T10:00:00.000Z` as ActivityEvent["occurredAt"],
    });

    const groups = groupByDay([
      build("e1", "2026-01-01"),
      build("e2", "2026-01-02"),
      build("e3", "2026-01-01"),
    ]);

    expect(groups).toHaveLength(2);
    expect(groups[0]?.day).toBe("2026-01-02");
    expect(groups[0]?.events).toHaveLength(1);
    expect(groups[1]?.day).toBe("2026-01-01");
    expect(groups[1]?.events).toHaveLength(2);
  });

  // Rows are scoped to the actor's org, and export needs activity:export.
  it("scopes the feed to the actor's organization", async () => {
    const other = await createTenant("activity-other", "growth");

    await expect(
      listActivity(other.actors.owner, {
        orgId: tenant.org.id,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const own = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(own.total).toBeGreaterThanOrEqual(1);

    // Exporting the audit log needs activity:export, which only admin+ holds.
    await expect(
      exportActivity(tenant.actors.member, {
        orgId: tenant.org.id,
        since: tenant.org.createdAt,
        until: tenant.org.createdAt,
        format: "json",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      exportActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        since: tenant.org.createdAt,
        until: tenant.org.createdAt,
        format: "json",
      }),
    ).resolves.toEqual(expect.any(String));
  });
});
/**
 * Domain events published by the service layer.
 *
 * Services stay decoupled from notifications, search, the audit log and
 * webhooks by announcing facts on the bus. If an event stops firing — or fires
 * with the wrong payload — every one of those concerns silently stops working,
 * which is why the contract is pinned here rather than through its consumers.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("events");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("issue.created", () => {
  it("is emitted once per created issue, carrying the actor and the issue", async () => {
    const seen = capture("issue.created");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Emit me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      issueId: issue.id,
      projectId: tenant.project.id,
      title: "Emit me",
      assigneeId: tenant.userIds.admin,
      priority: "none",
    });
    expect(seen[0]?.occurredAt).toEqual(expect.any(String));
  });

  it("is not emitted when the create is rejected", async () => {
    const seen = capture("issue.created");

    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, tenant.project.id),
      ),
    ).rejects.toThrow();

    expect(seen).toHaveLength(0);
  });
});

describe("issue.status_changed", () => {
  it("carries both ends of the transition", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Move me" }),
    );

    const seen = capture("issue.status_changed");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ from: "backlog", to: "in_progress" });
  });

  it("stays silent when the status did not actually move", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "No-op move" }),
    );

    const seen = capture("issue.status_changed");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "backlog",
    });

    expect(seen).toHaveLength(0);
  });
});

describe("issue.assigned", () => {
  it("reports the previous assignee alongside the new one", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Reassign me",
        assigneeId: tenant.userIds.member,
      }),
    );

    const seen = capture("issue.assigned");
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.admin,
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      previousAssigneeId: tenant.userIds.member,
      assigneeId: tenant.userIds.admin,
    });
  });

  it("falls back to issue.updated when the issue is un-assigned", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Unassign me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    const assigned = capture("issue.assigned");
    const updated = capture("issue.updated");

    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    expect(assigned).toHaveLength(0);
    expect(updated).toHaveLength(1);
    expect(updated[0]?.changedFields).toEqual(["assigneeId"]);
  });
});

describe("comment.created", () => {
  it("carries the mentions resolved server-side", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Discuss me" }),
    );

    const seen = capture("comment.created");
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Taking a look, @owner",
      parentId: null,
      mentionedUserIds: [],
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]?.mentionedUserIds).toEqual([tenant.userIds.owner]);
  });
});

describe("project.archived", () => {
  it("reports how many issues the cascade took with it", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Cascade",
      slug: "cascade",
      key: "CAS",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "Goes with it" }),
    );

    const seen = capture("project.archived");
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
