528	/** Groups a feed page by calendar day, newest day first. */
529	export function groupByDay(
530	  events: readonly ActivityEvent[],
531	): readonly ActivityGroup[] {
532	  const byDay = new Map<string, ActivityEvent[]>();
533	
534	  for (const event of events) {
535	    const day = event.occurredAt.slice(0, 10);
536	    const bucket = byDay.get(day) ?? [];
537	    bucket.push(event);
538	    byDay.set(day, bucket);
539	  }
540	
541	  return [...byDay.entries()]
542	    .sort(([a], [b]) => (a < b ? 1 : -1))
543	    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
544	}
