694	/**
695	 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
696	 *
697	 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
698	 */
699	import { subscribe } from "@/lib/event-bus";
700	import { createLogger } from "@/lib/logger";
701	import { enqueue } from "@/server/jobs/queue";
702	import { toIsoTimestamp } from "@/types/common";
703	import { registerActivityListeners } from "./activity-service";
704	import { registerSearchListeners } from "./search-service";
705	import { registerUsageListeners } from "./usage-service";
706	import { registerWebhookListeners } from "./webhook-service";
707	import type { Unsubscribe } from "@/types/event";
708	
709	/**
710	 * Importing this module also loads `notification-service` transitively, which
711	 * attaches the notification fan-out on first import — that hub has no
712	 * `register*` entry point of its own.
713	 */
714	import "./notification-service";
715	
716	const logger = createLogger("event-registry");
717	
718	/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
719	let detach: Unsubscribe | null = null;
720	
721	/**
722	 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
723	 * runs per server process, but a hot reload in dev can call it again and must
724	 * not double-deliver every event.
725	 */
726	export function registerEventHandlers(): void {
727	  if (detach !== null) return;
728	
729	  const offs: Unsubscribe[] = [
730	    registerActivityListeners(),
731	    registerSearchListeners(),
732	    registerUsageListeners(),
733	    registerWebhookListeners(),
734	    registerDigestBridge(),
735	  ];
736	
737	  detach = () => {
738	    for (const off of offs) off();
739	  };
740	
741	  logger.info("event handlers registered", { groups: offs.length });
742	}
