749	/**
750	 * The one piece of wiring that belongs to no single service: turning a
751	 * `digest.due` event into a queued job. Keeping it here rather than inside
752	 * `DigestService` stops the service layer from depending on the job layer.
753	 */
754	function registerDigestBridge(): Unsubscribe {
755	  return subscribe("digest.due", (payload) => {
756	    enqueue({
757	      id: `digest:${payload.orgId}:${payload.recipientId}`,
758	      kind: "digest-email",
759	      runAt: toIsoTimestamp(new Date()),
760	      attempts: 0,
761	      payload: {
762	        orgId: payload.orgId,
763	        recipientId: payload.recipientId,
764	        windowStart: payload.windowStart,
765	      },
766	    });
767	  });
