769	import type {
770	  EventHandler,
771	  TaskflowEventMap,
772	  TaskflowEventPayload,
773	  TaskflowEventType,
774	  Unsubscribe,
775	} from "@/types/event";
776	
777	/**
778	 * In-process, typed publish/subscribe bus.
779	 *
780	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
781	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
782	 * every reactive concern `subscribe()`s at module init (see
783	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
784	 * throwing handler never fails the emit or the sibling handlers.
785	 */
786	
787	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
788	
789	const handlers = new Map<TaskflowEventType, HandlerSet>();
790	
791	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
792	
793	/** Registers a handler for one event type. Call the return value to detach. */
794	export function subscribe<K extends TaskflowEventType>(
795	  type: K,
796	  handler: EventHandler<K>,
797	): Unsubscribe {
798	  const set = handlers.get(type) ?? new Set();
799	  set.add(handler as EventHandler<TaskflowEventType>);
800	  handlers.set(type, set);
801	  return () => {
802	    set.delete(handler as EventHandler<TaskflowEventType>);
803	  };
804	}
805	
806	/** Registers a handler that detaches itself after the first delivery. */
807	export function subscribeOnce<K extends TaskflowEventType>(
808	  type: K,
809	  handler: EventHandler<K>,
810	): Unsubscribe {
811	  const off = subscribe(type, (payload) => {
812	    off();
813	    return handler(payload);
814	  });
815	  return off;
816	}
817	
818	/**
819	 * Publishes an event to every subscriber. Resolves once all handlers settle;
820	 * rejected handlers are reported to the error sinks, never rethrown.
821	 */
822	export async function emit<K extends TaskflowEventType>(
823	  type: K,
824	  payload: TaskflowEventPayload<K>,
825	): Promise<void> {
826	  const set = handlers.get(type);
827	  if (!set || set.size === 0) return;
828	
829	  const results = await Promise.allSettled(
830	    [...set].map(async (handler) => {
831	      await (handler as EventHandler<K>)(payload);
832	    }),
833	  );
834	
835	  for (const result of results) {
836	    if (result.status === "rejected") {
837	      reportHandlerError(type, result.reason);
838	    }
839	  }
840	}
841	
842	/** Fire-and-forget variant for call sites that must not await delivery. */
843	export function emitAndForget<K extends TaskflowEventType>(
844	  type: K,
845	  payload: TaskflowEventPayload<K>,
846	): void {
847	  void emit(type, payload).catch((error: unknown) => {
848	    reportHandlerError(type, error);
849	  });
850	}
851	
852	export function onHandlerError(
853	  sink: (type: TaskflowEventType, error: unknown) => void,
854	): Unsubscribe {
855	  errorSinks.add(sink);
856	  return () => {
857	    errorSinks.delete(sink);
858	  };
859	}
860	
861	function reportHandlerError(type: TaskflowEventType, error: unknown): void {
862	  for (const sink of errorSinks) {
863	    try {
864	      sink(type, error);
865	    } catch {
866	      // A failing error sink must never escalate.
867	    }
868	  }
869	}
870	
871	/** Number of live subscribers for an event; used by tests and diagnostics. */
872	export function subscriberCount(type: TaskflowEventType): number {
873	  return handlers.get(type)?.size ?? 0;
874	}
875	
876	/** Detaches every handler. Test-only — never call from application code. */
877	export function resetEventBus(): void {
878	  handlers.clear();
879	  errorSinks.clear();
880	}
