927	    const { organization } = await getOrganizationSummary(actor, actor.orgId);
928	
929	    if (!can(actor, "activity:export", { kind: "activity", orgId: actor.orgId })) {
930	      return failure("forbidden", "Exporting the audit log requires an admin.");
931	    }
932	
933	    if (!isEnabled("csv_export", buildFlagContext(actor, organization))) {
934	      return failure("forbidden", "CSV export is not included in this plan.");
935	    }
936	
937	    const parsed = exportActivitySchema.safeParse({
938	      orgId: actor.orgId,
