969	
970	function toRow(
971	  event: ActivityEvent,
972	): Record<string, string | number | boolean | null> {
973	  return {
974	    occurredAt: event.occurredAt,
975	    action: event.action,
976	    actorId: event.actorId,
977	    subjectKind: event.subjectKind,
978	    subjectId: event.subjectId,
979	    projectId: event.projectId,
980	    summary: event.summary,
981	  };
982	}
983	/**
984	 * Private paging helpers shared by the repositories in this directory.
985	 *
986	 * Not part of the public data-access surface — repositories re-export nothing
987	 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
988	 * so a page boundary is stable even when two rows share a `created_at`.
989	 */
990	import { sql } from "drizzle-orm";
991	import { decodeCursor, encodeCursor } from "./base-repository";
992	import { makePage } from "@/types/common";
993	import type { Page } from "@/types/common";
994	import type { SQL } from "drizzle-orm";
995	import type { SQLiteColumn } from "drizzle-orm/sqlite-core";
996	
997	export interface KeysetSort {
998	  readonly sortColumn: SQLiteColumn;
999	  readonly idColumn: SQLiteColumn;
1000	}
1001	
1002	/**
1003	 * Predicate that resumes a descending listing after `cursor`. Returns
1004	 * `undefined` for a first page or an unparseable cursor — a bad cursor
1005	 * degrades to "start from the top", never to an error page.
1006	 */
1007	export function keysetPredicate(
1008	  sort: KeysetSort,
1009	  cursor: string | null | undefined,
1010	): SQL | undefined {
1011	  if (!cursor) return undefined;
1012	  const decoded = decodeCursor(cursor);
1013	  if (!decoded) return undefined;
1014	
1015	  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
1016	}
1017	
1018	/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
1019	export function probeLimit(limit: number): number {
1020	  return Math.max(1, Math.min(limit, 100)) + 1;
1021	}
1022	
1023	/**
1024	 * Turns an over-fetched row array into a `Page`, dropping the probe row and
1025	 * deriving the next cursor from the last row that survived.
1026	 */
1027	export function toPage<TRow, TOut>(
1028	  rows: readonly TRow[],
1029	  limit: number,
1030	  total: number,
1031	  map: (row: TRow) => TOut,
1032	  cursorOf: (row: TRow) => { id: string; sortValue: string },
1033	): Page<TOut> {
1034	  const capped = Math.max(1, Math.min(limit, 100));
1035	  const hasMore = rows.length > capped;
1036	  const visible = hasMore ? rows.slice(0, capped) : rows;
1037	  const last = visible.at(-1);
1038	
1039	  const nextCursor =
1040	    hasMore && last
1041	      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
1042	      : null;
1043	
1044	  return makePage(visible.map(map), nextCursor, total);
1045	}
1046	
1047	/** Drops the `undefined` slots so `and(...)` never sees a hole. */
1048	export function compact(
1049	  ...predicates: readonly (SQL | undefined)[]
1050	): readonly SQL[] {
1051	  return predicates.filter((value): value is SQL => value !== undefined);
1052	}
