328	export async function insertActivity(
329	  event: Omit<ActivityEvent, "id">,
330	): Promise<ActivityEvent> {
331	  const row = getDb()
332	    .insert(activityEvents)
333	    .values({
334	      id: newId(),
335	      orgId: event.orgId,
336	      action: event.action,
337	      actorId: event.actorId,
338	      subjectKind: event.subjectKind,
339	      subjectId: event.subjectId,
340	      projectId: event.projectId,
341	      summary: event.summary,
342	      // The summary is the audited fact; the scalar bag is presentation-only
343	      // and is reconstructed by the readers that need it.
344	      metadata: "{}",
345	      occurredAt: event.occurredAt,
346	    })
347	    .returning()
348	    .get();
