353	export async function listActivity(
354	  input: ActivityFilterInput,
355	): Promise<Page<ActivityEvent>> {
356	  const db = getDb();
357	  const sort = {
358	    sortColumn: activityEvents.occurredAt,
359	    idColumn: activityEvents.id,
360	  };
361	
362	  const filters = compact(
363	    orgPredicate(activityEvents.orgId, input.orgId),
364	    input.action === undefined || input.action.length === 0
365	      ? undefined
366	      : inArray(activityEvents.action, [...input.action]),
367	    input.actorId === undefined
368	      ? undefined
369	      : eq(activityEvents.actorId, input.actorId),
370	    input.projectId === undefined
371	      ? undefined
372	      : eq(activityEvents.projectId, input.projectId),
373	    input.subjectKind === undefined
374	      ? undefined
375	      : eq(activityEvents.subjectKind, input.subjectKind),
376	    input.since === undefined
377	      ? undefined
378	      : gte(activityEvents.occurredAt, input.since),
379	    // Half-open on the right so consecutive windows tile without overlap:
380	    // [since, until) followed by [until, next).
381	    input.until === undefined
382	      ? undefined
383	      : lt(activityEvents.occurredAt, input.until),
384	  );
385	
386	  const total = db
387	    .select({ value: count() })
388	    .from(activityEvents)
389	    .where(and(...filters))
390	    .get();
391	
392	  const rows = db
393	    .select()
394	    .from(activityEvents)
395	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
396	    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id))
397	    .limit(probeLimit(input.limit))
398	    .all();
399	
400	  return toPage(
401	    rows,
402	    input.limit,
403	    total?.value ?? 0,
404	    toActivityEvent,
405	    (row) => ({ id: row.id, sortValue: row.occurredAt }),
406	  );
407	}
