505	/**
506	 * Creates a project once the plan still has room for one. The key is derived
507	 * from the name when the caller left it blank, so the issue numbering scheme
508	 * (`TF-12`) is never invented at the call site.
509	 */
510	export async function createProject(
511	  actor: Actor,
512	  input: CreateProjectInput,
513	): Promise<Project> {
514	  assertOrgScope(actor, input.orgId);
515	  assertCan(actor, "project:create", orgResource(input.orgId));
516	
517	  const org = requireFound(
518	    await orgRepo.findOrgById(input.orgId),
519	    "Organization",
520	    input.orgId,
521	  );
522	
523	  const used = await projectRepo.countProjects(input.orgId);
524	  if (wouldExceedLimit(org.plan, "projects", used)) {
525	    throw new Error(
526	      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
527	    );
528	  }
529	
530	  const slug = await suggestProjectSlug(input.orgId, input.name);
531	
532	  const project = await projectRepo.insertProject({
533	    ...input,
534	    slug,
535	    key: input.key || projectKeyFromName(input.name),
536	  });
537	
538	  await emit("project.created", {
539	    ...actorEnvelope(actor),
540	    projectId: project.id,
541	    name: project.name,
542	    slug: project.slug,
543	  });
544	
545	  return project;
546	}
