710	/**
711	 * Role changes carry two rules the permission matrix cannot express:
712	 * nobody may grant a role above their own, and the last owner may not be
713	 * demoted. Both are checked after `can()` has had its say.
714	 */
715	export async function updateMemberRole(
716	  actor: Actor,
717	  input: UpdateMemberRoleInput,
718	): Promise<Member> {
719	  assertOrgScope(actor, input.orgId);
720	
721	  const member = requireFound(
722	    await memberRepo.findMemberById(input.orgId, input.memberId),
723	    "Member",
724	    input.memberId,
725	  );
726	  assertCan(actor, "member:update_role", memberResource(member));
727	
728	  if (!hasRoleAtLeast(actor.role, input.role)) {
729	    throw new Error(
730	      `A ${actor.role} cannot grant the ${input.role} role`,
731	    );
732	  }
733	
734	  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
735	
736	  const updated = await memberRepo.updateMemberRole(
737	    input.orgId,
738	    input.memberId,
739	    input.role,
740	  );
741	
742	  await emit("member.role_changed", {
743	    ...actorEnvelope(actor),
744	    memberId: updated.id,
745	    from: member.role,
746	    to: updated.role,
747	  });
748	
749	  return updated;
750	}
