797	/**
798	 * Throws when applying `nextRole` to `memberId` would leave the organization
799	 * without an owner. Exported because both the demote and the remove path need
800	 * it, and the invariant must not be stated twice.
801	 */
802	export async function assertLastOwnerRetained(
803	  orgId: OrgId,
804	  memberId: MemberId,
805	  nextRole: Role,
806	): Promise<void> {
807	  if (nextRole === "owner") return;
808	
809	  const member = await memberRepo.findMemberById(orgId, memberId);
810	  if (!member || member.role !== "owner") return;
811	
812	  const page = await memberRepo.listMembers({
813	    orgId,
814	    role: "owner",
815	    limit: OWNER_SCAN_LIMIT,
816	    cursor: null,
817	  });
818	
819	  const remaining = page.items.filter((row) => row.id !== memberId);
820	  if (remaining.length === 0) {
821	    throw new Error(
822	      "An organization must keep at least one owner; transfer ownership first",
823	    );
824	  }
825	}
826	/**
827	 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
828	 *
829	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
830	 */
831	import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
832	import { emit } from "@/lib/event-bus";
833	import { hashToken, randomToken } from "@/lib/hash";
834	import { assertCan } from "@/lib/permissions";
835	import { consumeRateLimit } from "@/lib/rate-limit";
836	import { assertOrgScope } from "@/lib/tenant";
837	import * as invitationRepo from "@/server/repositories/invitation-repository";
838	import * as memberRepo from "@/server/repositories/member-repository";
839	import * as orgRepo from "@/server/repositories/organization-repository";
840	import { toIsoTimestamp } from "@/types/common";
841	import { envelope, orgResource, requireFound } from "./_support";
842	import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
843	import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
