847	/** Token bucket protecting the invite mailer from being used as a spam relay. */
848	const INVITE_BUCKET = "member:invite";
849	
850	/** Default validity of a freshly minted invitation, in days. */
851	const DEFAULT_EXPIRY_DAYS = 14;
852	
853	export async function inviteMember(
854	  actor: Actor,
855	  input: InviteMemberInput,
856	): Promise<Invitation> {
857	  const [invitation] = await inviteMembers(actor, {
858	    orgId: input.orgId,
