866	/**
867	 * Bulk invite. The seat quota is checked once for the whole batch — inviting
868	 * five people into a plan with three free seats must fail as a batch rather
869	 * than half-succeeding — and the rate limit is charged per invite.
870	 */
871	export async function inviteMembers(
872	  actor: Actor,
873	  input: InviteMembersInput,
874	): Promise<readonly Invitation[]> {
875	  assertOrgScope(actor, input.orgId);
876	  assertCan(actor, "member:invite", orgResource(input.orgId));
877	
878	  const verdict = await consumeRateLimit(
879	    input.orgId,
880	    INVITE_BUCKET,
881	    input.invites.length,
882	  );
883	  if (!verdict.allowed) {
884	    throw new Error(
885	      `Invite rate limit reached; try again after ${verdict.resetAt}`,
886	    );
887	  }
888	
889	  const org = requireFound(
890	    await orgRepo.findOrgById(input.orgId),
891	    "Organization",
892	    input.orgId,
893	  );
894	
895	  const seatsUsed =
896	    (await memberRepo.countActiveMembers(input.orgId)) +
897	    (await invitationRepo.countPendingInvitations(input.orgId));
898	
899	  if (
900	    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
901	  ) {
902	    const limits = getPlanLimits(org.plan);
903	    throw new Error(
904	      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
905	    );
906	  }
907	
908	  const invitations: Invitation[] = [];
909	
910	  for (const invite of input.invites) {
911	    const token = randomToken(32);
912	    const invitation = await invitationRepo.insertInvitation(
913	      input.orgId,
914	      {
915	        orgId: input.orgId,
916	        email: invite.email,
917	        role: invite.role,
918	        expiresInDays: DEFAULT_EXPIRY_DAYS,
919	      },
920	      actor.userId,
921	      hashToken(token),
922	    );
923	
924	    invitations.push(invitation);
925	
926	    await emit("member.invited", {
927	      orgId: input.orgId,
928	      actorId: actor.userId,
929	      occurredAt: invitation.createdAt,
930	      email: invite.email,
931	      role: invite.role,
932	    });
933	  }
934	
935	  return invitations;
936	}
