938	/**
939	 * Accepting runs unauthenticated: the token is the credential, so there is no
940	 * `Actor` to scope against and every check has to come off the stored row.
941	 */
942	export async function acceptInvitation(
943	  userId: UserId,
944	  input: AcceptInvitationTokenInput,
945	): Promise<Member> {
946	  const invitation = requireFound(
947	    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
948	    "Invitation",
949	    "token",
950	  );
951	
952	  if (invitation.revokedAt !== null) {
953	    throw new Error("That invitation has been revoked");
954	  }
955	  if (invitation.acceptedAt !== null) {
956	    throw new Error("That invitation has already been accepted");
957	  }
958	  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
959	    throw new Error("That invitation has expired");
960	  }
961	
962	  const existing = await memberRepo.findMember(invitation.orgId, userId);
963	  if (existing) return existing;
964	
965	  const member = await memberRepo.insertMember(
966	    invitation.orgId,
967	    userId,
968	    invitation.role,
969	    invitation.invitedBy,
970	  );
971	
972	  await invitationRepo.markInvitationAccepted(
973	    invitation.orgId,
974	    invitation.id,
975	    toIsoTimestamp(new Date()),
976	  );
977	
978	  await emit("member.joined", {
979	    ...envelope(invitation.orgId, userId),
980	    memberId: member.id,
981	    userId,
982	    role: member.role,
983	  });
984	
985	  return member;
986	}
