996	/**
997	 * Re-issuing does not mint a new row: the original is revoked and replaced so
998	 * the audit trail keeps both, and the old link stops working immediately.
999	 */
1000	export async function resendInvitation(
1001	  actor: Actor,
1002	  invitationId: InvitationId,
1003	): Promise<Invitation> {
1004	  assertOrgScope(actor, actor.orgId);
1005	  assertCan(actor, "member:invite", orgResource(actor.orgId));
1006	
1007	  const previous = requireFound(
1008	    await invitationRepo
1009	      .listPendingInvitations(actor.orgId)
1010	      .then((rows) => rows.find((row) => row.id === invitationId) ?? null),
1011	    "Invitation",
1012	    invitationId,
1013	  );
1014	
1015	  await invitationRepo.revokeInvitation(actor.orgId, invitationId);
1016	
1017	  return inviteMember(actor, {
1018	    orgId: actor.orgId,
1019	    email: previous.email,
1020	    role: previous.role === "owner" ? "admin" : previous.role,
1021	  });
1022	}
