1048	/**
1049	 * Creates an organization and everything it cannot exist without: the owner's
1050	 * membership row and a subscription. Sign-up and "create another workspace"
1051	 * both land here, which is why it takes a bare `ownerId` rather than an
1052	 * `Actor` — there is no membership to build one from yet.
1053	 */
1054	export async function createOrganization(
1055	  ownerId: UserId,
1056	  input: CreateOrganizationInput,
1057	): Promise<Organization> {
1058	  assertValidSlug(input.slug);
1059	
1060	  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
1061	  const slug = uniqueSlug(input.slug, taken);
1062	
1063	  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);
1064	
1065	  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
1066	  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
1067	  await usageRepo.recomputeUsage(org.id);
1068	
1069	  await emit("member.joined", {
1070	    ...envelope(org.id, ownerId),
1071	    memberId: owner.id,
1072	    userId: ownerId,
1073	    role: owner.role,
1074	  });
1075	
1076	  return org;
1077	}
