s=s[:a]+r'''/**
 * The project an issue belongs to, for rows whose event names only the issue
 * (comments). A missing issue leaves the row unattributed rather than unwritten.
 */
async function projectOfIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<ProjectId | null> {
  try {
    const issue = await issueRepo.findIssueById(orgId, issueId);
    return issue?.projectId ?? null;
  } catch {
    return null;
  }
}

/**
 * Attaches one handler per audited event type. Called once from
 * `event-registry`; the returned function detaches all of them, which is what
 * the test suite uses to keep the bus clean between cases.
 *
 * Every row takes its actor and its time from the event envelope: the actor is
 * whoever performed the action, and the time is when it happened, not when
 * this handler got round to writing it.
 */
export function registerActivityListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("project.created", async (payload) => {
      await record(payload.orgId, "project.created", {
        actorId: payload.actorId,
        subjectKind: "project",
        subjectId: payload.projectId,
        projectId: payload.projectId,
        summary: `Created project ${payload.name}`,
        metadata: { name: payload.name, slug: payload.slug },
        occurredAt: payload.occurredAt,
      });
    }),
    subscribe("project.updated", async (payload) => {
      const fields = [...(payload.changedFields ?? [])];
      await record(payload.orgId, "project.updated", {
        actorId: payload.actorId,
        subjectKind: "project",
        subjectId: payload.projectId,
        projectId: payload.projectId,
        summary:
          fields.length === 0
            ? "Updated project"
            : `Updated project (${fields.join(", ")})`,
        metadata: { changedFields: fields.join(",") },
        occurredAt: payload.occurredAt,
      });
    }),
    subscribe("project.archived", async (payload) => {
      await record(payload.orgId, "project.archived", {
        actorId: payload.actorId,
        subjectKind: "project",
        subjectId: payload.projectId,
        projectId: payload.projectId,
        summary: `Archived project with ${payload.issuesArchived} issues`,
        metadata: { issuesArchived: payload.issuesArchived },
        occurredAt: payload.occurredAt,
      });
    }),
    subscribe("project.restored", async (payload) => {
      await record(payload.orgId, "project.restored", {
        actorId: payload.actorId,
        subjectKind: "project",
        subjectId: payload.projectId,
        projectId: payload.projectId,
        summary: "Restored project",
        occurredAt: payload.occurredAt,
      });
    }),
    subscribe("issue.created", async (payload) => {
      await record(payload.orgId, "issue.created", {
        actorId: payload.actorId,
        subjectKind: "issue",
        subjectId: payload.issueId,
        projectId: payload.projectId,
        summary: `Created issue "${payload.title}"`,
        metadata: {
          title: payload.title,
          priority: payload.priority,
          assigneeId: payload.assigneeId,
        },
        occurredAt: payload.occurredAt,
      });
    }),
    subscribe("issue.updated", async (payload) => {
      const fields = [...(payload.changedFields ?? [])];
      await record(payload.orgId, "issue.updated", {
        actorId: payload.actorId,
        subjectKind: "issue",
        subjectId: payload.issueId,
        projectId: payload.projectId,
        summary:
          fields.length === 0
            ? "Updated issue"
            : `Updated issue (${fields.join(", ")})`,
        metadata: { changedFields: fields.join(",") },
